{
  "items": [
    {
      "title": "Hessisches Statistisches Informationssystem (HESIS) – Historical Statistics for Hesse",
      "url_or_doi": "https://statistik.hessen.de/unsere-zahlen/datenbank-hesis",
      "justification": "Official statistical database maintained by the Hessian Statistical Office. Contains regional statistics for Hesse, with some historical series extending back to the 1970s. Potentially useful for investigating employment conditions, workforce characteristics, and occupational health-related indicators during 1980–1989. Data can be filtered geographically and exported to Excel. However, the availability of specific occupational accident and disease statistics for the 1980s has not been confirmed."
    },
    {
      "title": "Development of Occupational Accidents per 1,000 Full-Time Workers Since 1960 (Entwicklung der Arbeitsunfälle absolut und je 1.000 Vollarbeiter ab 1960)",
      "url_or_doi": "https://data.gov.de/suche/daten/entwicklung-der-arbeitsunfalle-absolut-und-je-1-000-vollarbeiter-ab-1960",
      "justification": "Historical dataset published by Germany's Federal Institute for Occupational Safety and Health (BAuA). Covers 1960–2016, including the entire 1980s. Provides annual figures for reportable workplace accidents, fatal occupational accidents, and new accident-related pensions. Data are available in CSV format and categorized by accident insurance institution. Particularly relevant for examining occupational safety trends during the 1980s. However, the dataset primarily provides nationwide statistics rather than Hesse-specific observations."
    },
    {
      "title": "Development of Occupational Diseases Since 1960 (Entwicklung der Berufskrankheiten ab 1960)",
      "url_or_doi": "https://data.gov.de/suche/daten/entwicklung-der-berufskrankheiten-ab-1960",
      "justification": "Official historical occupational disease dataset published by BAuA through Germany's national open-data portal. Includes annual statistics on suspected occupational diseases, recognized occupational diseases, occupational disease pensions, and deaths attributable to occupational illnesses. Covers the 1980s and is available in CSV format. Useful for studying long-term changes in occupational disease recognition and compensation. Geographic coverage is national, so Hesse-specific analysis would require supplementary regional records."
    },
    {
      "title": "DGUV Historical Occupational Accident Statistics (Arbeitsunfallgeschehen)",
      "url_or_doi": "https://publikationen.dguv.de/statistiken/arbeitsunfallgeschehen/",
      "justification": "Official publication repository maintained by the German Social Accident Insurance organization (DGUV). Provides statistical reports concerning occupational accidents and occupational diseases, including historical publications. Potentially valuable for locating original accident insurance statistics from the 1980s, particularly reports covering workplace injuries, occupational diseases, and insurance claims. Historical publications may contain sector-specific information relevant to Hesse. Availability of regional breakdowns and complete 1980–1989 coverage requires verification."
    },
    {
      "title": "DGUV Occupational Accident and Disease Statistics – Publications and Historical Time Series",
      "url_or_doi": "https://www.dguv.de/de/zahlen-fakten/veroeffentlichungen/index.jsp",
      "justification": "Official DGUV statistics and publications portal containing occupational accident and disease reports, statistical summaries, and historical time series. Relevant for reconstructing workplace injury and occupational disease trends during the 1980s. Offers an additional source for historical insurance statistics and potentially regional information. The available historical data are primarily national, and Hesse-specific figures have not been verified."
    },
    {
      "title": "Historical Statistics on German Social Policy Since 1945 (Statistik zur Geschichte der Sozialpolitik in Deutschland seit 1945)",
      "url_or_doi": "https://d-nb.info/1192124111/34",
      "justification": "Historical statistical publication containing annual data on German social policy, including occupational diseases and related insurance statistics. The available tables include observations for every year from 1980 through 1989, making the source useful for quantitative historical research. Occupational disease figures can help contextualize occupational health developments in Hesse within broader West German trends. The publication is not exclusively focused on Hesse, and regional disaggregation must be checked."
    },
    {
      "title": "German Federal Government Report: Development of Occupational Accidents, Occupational Diseases, and Insurance Expenditure Since 1960",
      "url_or_doi": "https://dserver.bundestag.de/btd/15/023/1502300.pdf",
      "justification": "Official German parliamentary publication containing historical annual statistical tables on occupational accidents, occupational diseases, disability pensions, and accident insurance expenditure. Includes continuous observations from 1960 through the 1980s. Suitable for analyzing occupational health indicators and changes in workplace safety across the decade. Figures primarily describe Germany as a whole rather than Hesse specifically, but provide useful historical benchmarks."
    },
    {
      "title": "Hesse Statistical Office – Historical Statistical Publications and Regional Statistics",
      "url_or_doi": "https://statistik.hessen.de/publikationen",
      "justification": "Official publication portal of the Hessian Statistical Office. Provides access to regional statistical reports and publications concerning Hesse. Potentially useful for identifying historical statistical yearbooks and regional data on employment, economic sectors, and health during the 1980s. These publications may provide workforce denominators or regional context for occupational health research. Specific occupational health tables from 1980–1989 have not been confirmed."
    },
    {
      "title": "Hesse Statistical Office – Historical Data Requests and Statistical Services",
      "url_or_doi": "https://statistik.hessen.de/ueber-uns/datenanfragen-und-services",
      "justification": "Official access point for requesting statistical information from the Hessian Statistical Office. Particularly relevant when historical regional statistics are unavailable through public online databases. Researchers can inquire about archived workplace accident statistics, occupational disease records, employment-related health indicators, and statistical publications covering Hesse between 1980 and 1989. This is a data-access service rather than a downloadable dataset, but it may help locate Hesse-specific historical records."
    }
  ]
}
